SELECT name,posting_date,company,customer,total,discount_amount,net_total,tax_amount,grand_total,outstanding_amount,update_stock,docstatus FROM "tabSales Invoice" WHERE (%(company)s='' OR company=%(company)s) AND (%(customer)s='' OR customer=%(customer)s) AND (%(from_date)s='' OR posting_date>=%(from_date)s) AND (%(to_date)s='' OR posting_date<=%(to_date)s) ORDER BY posting_date,name
